const CosmicWeatherBanner = () => {
    const now = new Date();
    const dayData = PLANET_OF_DAY[now.getDay()];
    const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const dateStr = `${dayNames[now.getDay()]}, ${now.getDate()} ${monthNames[now.getMonth()]} ${now.getFullYear()}`;

    const [tipIndex, setTipIndex] = useState(0);
    const [show, setShow] = useState(true);

    // Rotate tips every 4 seconds
    useEffect(() => {
        const interval = setInterval(() => {
            setTipIndex(i => (i + 1) % LUNAR_TIPS.length);
        }, 4000);
        return () => clearInterval(interval);
    }, []);

    if (!show) return null;

    return (
        <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            style={{
                width: '100%',
                background: `linear-gradient(90deg, rgba(4,2,14,0.98) 0%, rgba(${dayData.color === '#fbbf24' ? '60,35,5' : '30,5,60'},0.98) 50%, rgba(4,2,14,0.98) 100%)`,
                borderBottom: `1px solid ${dayData.color}22`,
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                padding: '0 52px', height: '36px', fontSize: '11px',
                fontFamily: 'Inter, sans-serif', letterSpacing: '0.06em',
                position: 'fixed', top: 0, zIndex: 102, overflow: 'hidden',
            }}
        >
            {/* Left: date + planetary ruler */}
            <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                <span style={{ color: '#4b3e68' }}>{dateStr}</span>
                <div style={{ width: '1px', height: '14px', background: 'rgba(139,92,246,0.25)' }} />
                <span style={{ color: dayData.color, fontWeight: 600 }}>
                    Today's Ruler: {dayData.planet}
                </span>
                <span style={{ color: '#4b3e68' }}>┬╖</span>
                <span style={{ color: '#5b4e78' }}>{dayData.energy}</span>
            </div>

            {/* Center: rotating tips ticker */}
            <div style={{ flex: 1, textAlign: 'center', overflow: 'hidden', padding: '0 40px' }}>
                <AnimatePresence mode="wait">
                    <motion.span
                        key={tipIndex}
                        initial={{ opacity: 0, y: 8 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -8 }}
                        transition={{ duration: 0.4 }}
                        style={{ color: '#7060a0', fontStyle: 'italic', whiteSpace: 'nowrap' }}
                    >
                        {LUNAR_TIPS[tipIndex]}
                    </motion.span>
                </AnimatePresence>
            </div>

            {/* Right: close */}
            <motion.button
                whileHover={{ color: '#c4b5fd' }}
                onClick={() => setShow(false)}
                style={{ background: 'none', border: 'none', color: '#3b3058', cursor: 'pointer', fontSize: '14px', padding: '0', fontFamily: 'Inter' }}
            >
                ├ù
            </motion.button>
        </motion.div>
    );
};

export default CosmicWeatherBanner;

import React, { useState, useEffect, useRef } from 'react';
import { Volume2, Square } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { generateDailyHoroscope } from '../services/geminiService';

const SIGNS = [
  { name: 'Aries', symbol: 'ΓÖê', color: '#ff6b8a' },
  { name: 'Taurus', symbol: 'ΓÖë', color: '#8bc34a' },
  { name: 'Gemini', symbol: 'ΓÖè', color: '#ffeb3b' },
  { name: 'Cancer', symbol: 'ΓÖï', color: '#b3e5fc' },
  { name: 'Leo', symbol: 'ΓÖî', color: '#ff9800' },
  { name: 'Virgo', symbol: 'ΓÖì', color: '#a1887f' },
  { name: 'Libra', symbol: 'ΓÖÄ', color: '#f48fb1' },
  { name: 'Scorpio', symbol: 'ΓÖÅ', color: '#e53935' },
  { name: 'Sagittarius', symbol: 'ΓÖÉ', color: '#9c27b0' },
  { name: 'Capricorn', symbol: 'ΓÖæ', color: '#607d8b' },
  { name: 'Aquarius', symbol: 'ΓÖÆ', color: '#00bcd4' },
  { name: 'Pisces', symbol: 'ΓÖô', color: '#7c4dff' },
];

const DailyHoroscope = () => {
  const [selected, setSelected] = useState(null);
  const [horoscopeData, setHoroscopeData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const synthRef = useRef(window.speechSynthesis);

  // Stop talking when unmounting or changing sign
  useEffect(() => {
    if (synthRef.current) synthRef.current.cancel();
    setIsPlaying(false);
  }, [selected]);

  const handlePlayVoice = () => {
    if (isPlaying) {
      synthRef.current.cancel();
      setIsPlaying(false);
      return;
    }

    if (!horoscopeData?.horoscope) return;

    setIsPlaying(true);
    const utterance = new SpeechSynthesisUtterance(horoscopeData.horoscope);

    // Try to find an ethereal/female voice if available
    const voices = synthRef.current.getVoices();
    const preferredVoice = voices.find(v => v.name.includes('Google UK English Female') || v.name.includes('Samantha') || v.name.includes('Female')) || voices[0];
    if (preferredVoice) utterance.voice = preferredVoice;

    utterance.rate = 0.85; // Slower, more relaxing
    utterance.pitch = 0.9;

    utterance.onend = () => setIsPlaying(false);
    utterance.onerror = () => setIsPlaying(false);

    synthRef.current.speak(utterance);
  };

  useEffect(() => {
    if (!selected) return;
    let cancelled = false;

    const fetchHoroscope = async () => {
      setLoading(true);
      setHoroscopeData(null);
      try {
        const raw = await generateDailyHoroscope(selected.name);
        if (!cancelled) {
          const data = JSON.parse(raw);
          setHoroscopeData(data);
        }
      } catch (err) {
        if (!cancelled) {
          setHoroscopeData({
            horoscope: `Today brings powerful energy for ${selected.name}. Trust your instincts and embrace new possibilities. The universe supports your deepest desires.`,
            luckyColor: 'Cosmic Purple',
            luckyNumber: 7,
            energy: 8,
          });
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    fetchHoroscope();
    return () => { cancelled = true; };
  }, [selected]);

  return (
    <section style={{ padding: '80px 0', position: 'relative' }}>
      <div style={{ maxWidth: '1000px', margin: '0 auto', padding: '0 48px' }}>
        {/* Header */}
        <div style={{ textAlign: 'center', marginBottom: '40px' }}>
          <motion.p initial={{ opacity: 0, y: 10 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }}
            style={{ fontFamily: 'Inter', fontSize: '11px', letterSpacing: '0.22em', color: '#8b5cf6', textTransform: 'uppercase', marginBottom: '12px' }}>
            Γ£ª AI-Powered Insight
          </motion.p>
          <motion.h2 initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: 0.1 }}
            style={{ fontFamily: 'Great Vibes, cursive', fontSize: 'clamp(40px, 6vw, 64px)', background: 'linear-gradient(135deg, #ffffff 0%, #c4b5fd 100%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text', margin: '0 0 12px 0', fontWeight: 400 }}>
            Today's Horoscope
          </motion.h2>
          <motion.p initial={{ opacity: 0 }} whileInView={{ opacity: 1 }} viewport={{ once: true }} transition={{ delay: 0.2 }}
            style={{ fontFamily: 'Inter', fontSize: '14px', color: '#8070a8', maxWidth: '480px', margin: '0 auto', lineHeight: 1.8 }}>
            Select your zodiac sign to receive your personalised cosmic guidance for today.
          </motion.p>
        </div>

        {/* Sign selector */}
        <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', flexWrap: 'wrap', marginBottom: '32px' }}>
          {SIGNS.map((sign) => (
            <motion.button
              key={sign.name}
              whileHover={{ scale: 1.15, y: -4 }}
              whileTap={{ scale: 0.9 }}
              onClick={() => setSelected(sign)}
              style={{
                width: '48px', height: '48px', borderRadius: '50%',
                background: selected?.name === sign.name ? `${sign.color}25` : 'rgba(12,8,45,0.7)',
                border: `2px solid ${selected?.name === sign.name ? sign.color : 'rgba(139,92,246,0.15)'}`,
                fontSize: '22px', cursor: 'pointer',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                boxShadow: selected?.name === sign.name ? `0 0 20px ${sign.color}30` : 'none',
                transition: 'all 0.2s',
              }}
              title={sign.name}
            >
              {sign.symbol}
            </motion.button>
          ))}
        </div>

        {/* Horoscope card */}
        <AnimatePresence mode="wait">
          {selected && (
            <motion.div
              key={selected.name}
              initial={{ opacity: 0, y: 20, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -10, scale: 0.95 }}
              transition={{ duration: 0.4 }}
              style={{
                maxWidth: '600px', margin: '0 auto',
                background: 'rgba(10,6,38,0.85)',
                border: `1px solid ${selected.color}25`,
                borderRadius: '24px', padding: '36px',
                backdropFilter: 'blur(20px)',
                boxShadow: `0 20px 50px rgba(0,0,0,0.3), 0 0 30px ${selected.color}08`,
                position: 'relative', overflow: 'hidden',
              }}
            >
              {/* Top glow */}
              <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '2px', background: `linear-gradient(90deg, transparent, ${selected.color}, transparent)` }} />

              <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: '20px' }}>
                <div style={{
                  width: '56px', height: '56px', borderRadius: '50%',
