const Admin = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [password, setPassword] = useState('');
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(false);

    // Form state
    const [newProduct, setNewProduct] = useState({
        name: '', description: '', price: '', category: 'Water', image: 'Γ£¿'
    });

    // Mock authentication for demonstration
    const handleLogin = (e) => {
        e.preventDefault();
        if (password === 'admin123') { // Very simple auth for standard scope
            setIsAuthenticated(true);
            fetchProducts();
        } else {
            alert('Incorrect admin password. Try "admin123"');
        }
    };

    const fetchProducts = async () => {
        try {
            const res = await fetch('http://localhost:3001/api/products');
            if (res.ok) {
                const data = await res.json();
                setProducts(data);
            }
        } catch (error) {
            console.error('Failed to fetch products for admin', error);
        }
    };

    const handleAddProduct = async (e) => {
        e.preventDefault();
        if (!newProduct.name || !newProduct.price) return;

        setLoading(true);
        try {
            const res = await fetch('http://localhost:3001/api/products', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newProduct)
            });
            if (res.ok) {
                fetchProducts();
                setNewProduct({ name: '', description: '', price: '', category: 'Water', image: 'Γ£¿' });
            }
        } catch (error) {
            console.error('Add failed', error);
        } finally {
            setLoading(false);
        }
    };

